if(['start','resume'].includes(action)){const check=R.check(t,c);R.need(check.allowed,'当前设备、人员资格或许可检查不通过');R.need(body.confirmed===true,'安全条件确认必填');R.need(body.permitId===check.permit.id,'许可引用已变化');t.safetySnapshot={...copy(check),actorId:ctx.person,confirmedAt:new Date().toISOString()};t.status='in_progress';t.startedAt||=new Date().toISOString();}
