if(['start','resume','assign','execution','discoveries'].includes(action)&&t.status==='in_progress')t.executionActors=[...new Set([...(t.executionActors||[]),...(action==='assign'?[]:[ctx.person]),...(['start','resume','assign'].includes(action)?[t.primaryPersonId,...t.collaboratorIds]:[])])];
